from pages import *
from fig import *
i=15
def lit_palace(): return palace()+''.join(f'<circle cx="{x}" cy="{y}" r="1.6" fill="#ffd60a" stroke="none"/>' for x in range(-108,112,8) for y in (-4,-30,-58))
COV=covart('The illuminated Mysuru Palace at night, and in front of it a decorated elephant carrying a golden howdah with the image of Cāmuṇḍeśvarī',
 '<rect width="440" height="196" fill="#1f1a2e"/>'+g(270,150,1.3,lit_palace())+ground(440,220,150,'#4a3a2a')+g(130,200,1.3,elephant())+g(122,96,.35,devi(items=('trident','sword','lotus','abhaya')))+''.join(f'<circle cx="{x}" cy="{y}" r="1.8" fill="#fff8d0"/>' for x,y in [(30,30),(90,50),(400,30),(420,90)]))
pages=[foreword(i,['The series ends where it began, at home in Mysuru. For more than four hundred years the city has kept Navarātri as a royal festival, and today as the <b>Nāḍa Habba</b>, the festival of the whole state.','This part tells its story: the <b>Mahānavamī</b> of Vijayanagara, <b>Raja Woḍeyar’s</b> Dasarā at Śrīraṅgapaṭṇa in 1610, the move to Mysuru, the palace and the golden throne, <b>Cāmuṇḍī Hill</b>, and the great procession of the tenth day, the <b>Jambū Savāri</b>, to the banni tree. Then a last look at how the rest of India keeps the day.'],
 [('z','Is Mysuru Dasarā a religious festival or a royal one?'),('b','Both, always. The kings kept it as devotees of Cāmuṇḍeśvarī; the Goddess still leads the procession today.')]),
 glance([('Name','Mysuru Dasarā; Nāḍa Habba, “the festival of the land”'),('Roots','The Mahānavamī festival of the Vijayanagara kings at Hampi'),('Begun','1610, by Raja Woḍeyar I, at Śrīraṅgapaṭṇa'),('In Mysuru','From 1799, after the fall of Tipu Sultan and the Woḍeyars’ return'),('Presiding Goddess','Cāmuṇḍeśvarī of Cāmuṇḍī Hill'),('Highlight','The Jambū Savāri on Vijayadaśamī: the golden howdah on an elephant, from the palace to the Banni Maṇṭapa'),('Today','The state festival of Karnataka')],svg(560,170,'The palace, an elephant with the golden howdah, and Cāmuṇḍī Hill behind',ground(560,170,150,'#cfe0b8')+'<path d="M300 150 L440 50 L560 150z" fill="#8a9a6a" stroke="#111" stroke-width="2"/>'+g(160,150,.8,palace())+g(420,160,.8,elephant()))),
 reading('vijayanagara','THE MAHĀNAVAMĪ OF VIJAYANAGARA','Where the royal festival began',svg(560,190,'A tall stepped stone platform with carved friezes, a king seated on top watching a parade of elephants, horses and dancers',ground(560,190,170,'#e9d6c0')+''.join(f'<rect x="{180+k*20}" y="{170-(k+1)*24}" width="{200-k*40}" height="24" fill="#cbb89a" stroke="#111" stroke-width="2"/>' for k in range(4))+g(280,74,.6,person('#c0392b',seat=True))+g(80,170,.6,elephant(False))+g(470,170,.7,person('#7a3fa0'))+g(510,170,.7,person('#e0a800'))+lab(280,186,'the Mahānavamī platform, Hampi')),[
  '<b>An imperial festival.</b> The kings of <b>Vijayanagara</b> (14th to 16th centuries) celebrated Navarātri as the <b>Mahānavamī</b>, their greatest festival of the year, at their capital, Hampi.','<b>The platform.</b> At Hampi a great stone platform, now called the Mahānavamī Diṇṇe, still stands, its walls carved with processions, hunts, dancers and elephants. From it, the king is believed to have watched the festival.','<b>What visitors saw.</b> Foreign travellers to Vijayanagara described nine days of worship, wrestling, dances, fireworks, parades of elephants and horses, and the king receiving tribute from his nobles. These accounts are among the best descriptions of the festival we have.','<b>After the fall.</b> When Vijayanagara fell after the battle of 1565, the regional rulers who had served it carried the festival with them. The Woḍeyars of Mysuru were among them.'],
  [('z','So Mysuru inherited an empire’s festival?'),('b','Exactly. The city that remembered Vijayanagara’s Mahānavamī turned it into its own Dasarā.')],'Vijayanagara’s Mahānavamī: <b>the imperial root of the Mysuru Dasarā</b>.'),
 reading('wodeyar','RAJA WOḌEYAR AND THE WOḌEYARS','From Śrīraṅgapaṭṇa to Mysuru',svg(560,140,'A timeline: Vijayanagara, 1610 Śrīraṅgapaṭṇa, 1799 Mysuru, the twentieth century, and today',
  '<path d="M30 70 H530" stroke="#111" stroke-width="4"/>'+''.join(f'<circle cx="{x}" cy="70" r="10" fill="#ffd60a" stroke="#111" stroke-width="2"/>'+lab(x,45,a,11)+lab(x,100,b,10) for x,a,b in [(60,'1336–1565','Vijayanagara'),(180,'1610','Śrīraṅgapaṭṇa'),(300,'1799','to Mysuru'),(420,'1902–1940','Nalvaḍi’s era'),(510,'today','Nāḍa Habba')])),[
  '<b>1610.</b> <b>Raja Woḍeyar I</b> (ruled 1578–1617) took Śrīraṅgapaṭṇa, the old seat of the Vijayanagara viceroys, and made it his capital. In 1610 he began celebrating Navarātri there as a royal Dasarā on the Vijayanagara model. The festival’s count of years begins here.','<b>1610 to 1799.</b> For nearly two centuries the Dasarā was held at Śrīraṅgapaṭṇa. During the rule of Haidar Ali and Tipu Sultan, the Woḍeyar kings were sidelined.','<b>1799.</b> After Tipu’s fall, the Woḍeyars were restored at <b>Mysuru</b>, and the Dasarā moved with them. The first Dasarā in Mysuru is remembered as presided over by Mummaḍi Kṛṣṇarāja Woḍeyar (Kṛṣṇarāja Woḍeyar III), then a boy of five.','<b>The grand era.</b> Under Nalvaḍi Kṛṣṇarāja Woḍeyar (Kṛṣṇarāja Woḍeyar IV, 1902–1940) the Dasarā became famous across India, with the palace lit, exhibitions, music and the great procession.'],
  [('z','So Mysuru Dasarā is older than Mysuru as capital?'),('b','Yes. It began at Śrīraṅgapaṭṇa and came to Mysuru with the kings.')],'1610 at Śrīraṅgapaṭṇa, 1799 in Mysuru: <b>four centuries of Dasarā</b>.'),
 reading('palace','THE PALACE AND THE GOLDEN THRONE','The royal side of the nine days',svg(560,200,'The Mysuru Palace lit with rows of lights at night, with a small golden throne shown in an inset',
  '<rect width="560" height="200" fill="#1f1a2e"/>'+g(230,180,1.5,lit_palace())+g(470,90,1,'<rect x="-50" y="-60" width="100" height="100" rx="8" fill="#fff8ec" stroke="#111" stroke-width="2"/><path d="M-24 20 v-40 q24 -30 48 0 v40z" fill="#e0a800" stroke="#111" stroke-width="2"/><path d="M-30 20 h60" stroke-width="4"/>')+lab(470,150,'the throne',11)),[
  '<b>The palace lit.</b> Through the festival the Mysuru Palace, the Ambā Vilāsa, is lit with tens of thousands of bulbs every evening, a sight that has drawn visitors for a century.','<b>The golden throne.</b> The jewelled royal throne (<b>ratna siṃhāsana</b>) of the Woḍeyars is assembled for Navarātri. The Mahārāja sat on it to hold the <b>Dasarā durbar</b>, receiving nobles and honouring the Goddess.','<b>A vow kept.</b> During the nine days the king lived under a ritual vow, worshipping in the palace, and the royal family continues its private rites there today; we describe these from public reports and do not claim their details.','<b>The royal sword.</b> On Vijayadaśamī the royal sword is worshipped and, by tradition, taken in procession to the banni tree, remembering the kings who once rode out for victory.'],
  [('z','Does the family still sit on the throne?'),('b','Public reports say a private durbar continues inside the palace. The great public procession is now led by the Goddess.')],'Lit palace, golden throne, royal vow: <b>the palace keeps its Dasarā</b>.'),
 reading('chamundi','CĀMUṆḌĪ HILL','The Goddess of the city',svg(560,200,'Cāmuṇḍī Hill with its temple tower at the top and a long flight of steps winding up from the city',ground(560,200,180,'#cfe0b8')+'<path d="M40 180 L280 40 L520 180z" fill="#8a9a6a" stroke="#111" stroke-width="2.5"/>'+g(280,52,.8,'<path d="M-24 0 h48 l-8 -44 h-32z" fill="#e8c06a"/>'+''.join(f'<path d="M-20 {-k*10} h40" stroke-width="1"/>' for k in range(1,4))+'<circle cy="-50" r="4" fill="#e0a800"/>')+''.join(f'<rect x="{150+k*12}" y="{170-k*11}" width="12" height="4" fill="#f3e3c3"/>' for k in range(11))+lab(280,24,'Cāmuṇḍeśvarī temple')),[
  '<b>The family deity.</b> <b>Cāmuṇḍeśvarī</b>, the Devī who slew Mahiṣa, is the family deity (<i>kuladevatā</i>) of the Woḍeyars and the guardian of Mysuru. Her temple crowns <b>Cāmuṇḍī Hill</b> above the city ('+link(1,'Part 2')+').','<b>The thousand steps.</b> A flight of about a thousand stone steps climbs the hill, with a great monolithic Nandi on the way. Climbing them during Navarātri is a favourite vow.','<b>The festival begins here.</b> The Mysuru Dasarā is formally opened each year with worship of Cāmuṇḍeśvarī on the hill, and special worship continues in her temple through the nine nights.','<b>Read more.</b> Our <a href="/temples-of-india/around-mysuru/chamundeshwari/">Around Mysuru article on Cāmuṇḍeśvarī</a> tells the temple’s history and legends in full.'],
  [('z','The festival opens on the hill and ends on the street?'),('b','It opens with the Goddess in her temple and ends with the Goddess riding through her city.')],'Cāmuṇḍeśvarī of the hill: <b>the Goddess the whole festival is for</b>.'),
 reading('jambu','THE JAMBŪ SAVĀRI','The golden howdah',svg(560,210,'A long procession: a decorated lead elephant carrying the golden howdah with the Goddess, followed by more elephants, horses, a band and folk dancers',ground(560,210,180,'#e9d6c0')+g(110,190,1.3,elephant())+g(102,108,.33,devi(items=('trident','sword','lotus','abhaya')))+g(250,190,.8,elephant(False))+g(340,190,.8,elephant(False))+g(420,190,.8,person('#1d6fb8'))+g(450,190,.8,person('#c0392b'))+g(480,190,.8,person('#2a9d6f'))+g(520,190,.8,person('#e0a800'))+lab(110,206,'the golden howdah')+lab(470,206,'bands and folk troupes')),[
  '<b>The procession.</b> On Vijayadaśamī afternoon the <b>Jambū Savāri</b> leaves the palace. A trained lead elephant carries the <b>golden howdah</b> (<i>ambāri</i>), said to weigh about 750 kg, bearing the image of <b>Cāmuṇḍeśvarī</b>. Other elephants, cavalry, bands, tableaux and folk dancers from all over Karnataka follow.','<b>From king to Goddess.</b> In the time of the kings, the Mahārāja himself rode in the howdah. After the end of royal rule, the Goddess took his place: the procession now carries her image, and the Chief Minister offers flowers to her before it sets out.','<b>The name.</b> Many in Mysuru say “Jambū” comes from <b>Jambi</b> or <b>Śamī</b> Savāri, “the journey to the śamī tree”, since the procession’s goal is the banni tree. The spelling with “Jumbo”, suggesting elephants, is a later twist.','<b>The howdah’s age.</b> Reports say the golden howdah joined the festival after the move to Mysuru in 1799.'],
  [('z','Does the same elephant carry it every year?'),('b','A senior trained elephant leads for some years; the elephants come from the forest camps and practise with weights for weeks.')],'The golden howdah, the Goddess and the road to the banni tree: <b>the Jambū Savāri</b>.'),
 reading('banni','THE BANNI MAṆṬAPA','Where the procession ends',svg(560,190,'A large banni tree in an open ground, with a torchlight parade of horsemen carrying flaming torches in the evening',
  '<rect width="560" height="190" fill="#2a1d3a"/>'+ground(560,190,150,'#4a3a2a')+g(110,150,1.4,shami())+''.join(g(220+k*60,150,.7,'<path d="M-30 0 v-20 q0 -20 30 -22 h30 l10 4 l-4 30 h-10 v8 z" fill="#8a5a2a"/>')+g(225+k*60,110,.5,person('#c0392b'))+g(240+k*60,86,.6,'<path d="M0 0 v-20" stroke="#8a5a2a" stroke-width="3"/>'+flames()) for k in range(5))+lab(110,176,'the banni tree',11)),[
  '<b>The banni tree.</b> The procession ends at the <b>Banni Maṇṭapa</b>, on the city’s edge, where the banni (śamī) tree is worshipped, just as the Pāṇḍavas once honoured the tree that kept their weapons ('+link(14,'Part 15')+'). In the kings’ time the Mahārāja himself performed this worship, then returned in state.','<b>The torchlight parade.</b> In the evening the Banni Maṇṭapa grounds host the <b>Pañjina Kavāyatu</b>, the torchlight parade: mounted troops, displays of skill and fireworks to close the festival.','<b>An old pattern.</b> The journey out of the city to the śamī tree on the tenth day is the old royal <b>sīmollaṅghana</b>, the crossing of the boundary, kept alive in a modern city.','<b>The end.</b> With the torches the Dasarā closes; the dolls in Mysuru homes are laid down to sleep, and the city waits a year.'],
  [('z','So the whole procession is going to a tree?'),('b','To the tree, the Goddess and the old promise of victory. The tree is where the Pāṇḍavas got their bows back.')],'To the banni tree, then torches: <b>the Dasarā’s last evening</b>.'),
 reading('nadahabba','THE NĀḌA HABBA TODAY','A festival of the whole state',svg(560,180,'A crowd enjoying the festival: a music stage, an exhibition gate, wrestlers, and food stalls under strings of lights',ground(560,180,160,'#e9d6c0')+''.join(f'<circle cx="{x}" cy="40" r="3" fill="#ffd60a" stroke="#111" stroke-width="1"/>' for x in range(20,560,24))+'<path d="M0 40 q280 30 560 0" fill="none" stroke="#111"/>'+g(110,160,1,'<rect x="-60" y="-20" width="120" height="20" fill="#a8553a" stroke="#111" stroke-width="2"/>')+g(110,140,.8,person('#c0392b',seat=True))+g(140,110,.5,vina())+g(300,160,.9,person('#e0a800'))+g(330,160,.9,person('#3a3a40'))+'<rect x="420" y="100" width="100" height="60" fill="#fff3cf" stroke="#111" stroke-width="2"/>'+lab(110,176,'music')+lab(315,176,'wrestling')+lab(470,176,'exhibition')),[
  '<b>The people’s festival.</b> Since the end of royal rule, the State of Karnataka has organised the Dasarā, and it is officially the <b>Nāḍa Habba</b>, the state festival.','<b>Many festivals in one.</b> Alongside the worship come music and dance in the palace grounds, wrestling (a royal tradition), poetry gatherings, food festivals, sports, flower shows and the long-running Dasarā exhibition.','<b>At home.</b> Behind the spectacle, homes across old Mysuru keep the quieter Navarātri of this series: the doll steps, Sarasvatī Pūjā, Āyudha Pūjā and the banni leaves.','<b>Visiting.</b> We do not give dates or timings, which change each year; the Karnataka Tourism and Mysuru Dasarā official sites publish each year’s programme.'],
  [('z','Which part is the real Dasarā: the palace or the home?'),('b','Both. The city celebrates outside; the Goddess is worshipped inside. Mysuru needs both.')],'Music, wrestling, lights and the home altar: <b>the Nāḍa Habba</b>.'),
 cards('india','DASARĀ ACROSS INDIA','How others keep the tenth day',svg(560,170,'Four small scenes: Kullu valley deities carried in palanquins, a Bengali goddess immersed in a river, a Rāvaṇa effigy burning, and garbā dancers',g(80,150,.8,'<path d="M-30 0 h60 M-24 -8 h48 v-24 h-48z" fill="#e0a800"/>')+g(80,110,.4,god())+'<path d="M180 150 q40 -10 80 0" fill="#8fb8de" stroke="#111"/>'+g(220,150,.6,devi(items=('trident',)))+g(360,155,.7,effigy())+g(360,160,.7,flames())+''.join(g(460+k*28,150,.7,person(c)) for k,c in enumerate(['#c0392b','#e0a800','#2a9d6f']))),[
  ('🏔️','Kullu, Himachal','The Kullu Dasarā begins on Vijayadaśamī and runs a week: Raghunātha (Rāma) is drawn on a chariot and the valley’s village deities come in palanquins to meet him.'),
  ('🌊','Bengal','On Bijayā Daśamī the Goddess is bid farewell and her image immersed in the river; married women smear each other with vermilion (sindūr khelā), and families visit elders.'),
  ('🔥','The north','Rāmlīlā ends with Rāvaṇa, Kumbhakarṇa and Meghanāda burnt as giant effigies, most famously at Delhi’s Rāmlīlā grounds and Vārāṇasī’s Ramnagar.'),
  ('💃','Gujarat and beyond','The garbā nights end; and in Bastar (Chhattisgarh) a long Dasarā honours the local goddess Danteśvarī.')],
  [('z','So every region has its own tenth day?'),('b','Yes, and each one is someone’s home festival, as Mysuru’s is ours.')],'Kullu, Bengal, Delhi, Bastar, Mysuru: <b>one victory, many celebrations</b>.'),
 end(i,['<b>Roots.</b> The Mahānavamī of Vijayanagara at Hampi.','<b>1610.</b> Raja Woḍeyar began the Dasarā at Śrīraṅgapaṭṇa; it moved to Mysuru in 1799.','<b>Palace.</b> Lit through the nights; the golden throne and the royal vow.','<b>Jambū Savāri.</b> Cāmuṇḍeśvarī in the golden howdah, to the banni tree.','<b>Today.</b> The Nāḍa Habba of Karnataka.'],'That is the end of the series. Go back to '+link(0,'Part 1')+' for the map, or read the <a href="/devi/devi-mahatmya/">Devī Māhātmya</a> itself, the scripture behind every night.','The Mysuru Dasarā'),
 sources([('History:','Wikipedia, “Mysore Dasara” (Raja Woḍeyar I, 1610; Jambū Savāri; Banni Maṇṭapa; torchlight parade; name Jambi Savāri). Deccan Herald features (“A festival of firsts”, 1610–1799 at Śrīraṅgapaṭṇa, first Mysuru Dasarā under Mummaḍi Kṛṣṇarāja Woḍeyar; golden howdah after 1799; Hoysaḷa/Vijayanagara roots). Culture and Heritage, “Srirangapatna Dasara”.'),('Procession:','Gulf News and Outlook reports on the 750 kg golden howdah; Karnataka Tourism, “Mysuru Dasara”.'),('Regions:','Wikipedia, “Vijayadashami”, “Kullu Dussehra”, “Bastar Dussehra”.')],'the royal family’s private rites (from public reports only); the derivation of “Jambū” from “Śamī/Jambi”; the howdah’s exact weight; Vijayanagara details drawn from travellers’ accounts.','No dates or timings are given; check each year’s official programme.')]
build(i,'PART 16 OF 16 · PALACE · HOWDAH · BANNI',COV,'The palace lit, the Goddess on the elephant',
 'The story of <b>Mysuru’s Dasarā</b>: Vijayanagara’s Mahānavamī, <b>Raja Woḍeyar in 1610</b>, the move to Mysuru, the palace and throne, <b>Cāmuṇḍī Hill</b>, the <b>Jambū Savāri</b> and the banni tree, and the tenth day across India.',
 'The Mysuru Dasarā explained: the Mahānavamī of Vijayanagara, Raja Woḍeyar’s Dasarā at Śrīraṅgapaṭṇa in 1610, the move to Mysuru in 1799, the palace and golden throne, Cāmuṇḍī Hill, the Jambū Savāri with the golden howdah, the Banni Maṇṭapa and torchlight parade, the Nāḍa Habba today and Dasarā across India. Part 16 of the illustrated Navarātri series.',pages)
print('ok')
